Set<Multihash> queried = new HashSet<>();
for (int round = 0; round < 20 && !toQuery.isEmpty(); round++) {
    List<RoutingEntry> peers = toQuery.stream().limit(queryParallelism).toList();
    toQuery.removeAll(peers);
    peers.forEach(peer -> queried.add(peer.addresses.peerId));
    var responses = peers.stream()
            .map(peer -> getValueFromPeer(peer.addresses, publisher, us)
                    .completeOnTimeout(Optional.empty(), 5, TimeUnit.SECONDS))
            .toList();
    // Finish the current batch before checking the target: a slower peer may have a newer record.
    for (var response : responses) {
        response.join().ifPresent(result -> {
            result.record.filter(record -> record.publisher.equals(publisher))
                    .ifPresent(record -> candidates.add(record.value));
            for (PeerAddresses peer : result.closerPeers) {
                if (!queried.contains(peer.peerId) && hasTransportOverlap(peer)) {
                    toQuery.add(new RoutingEntry(Id.create(Hash.sha256(peer.peerId.toBytes()), 256), peer));
                }
            }
        });
    }
    candidates.removeIf(record -> !record.expiry.isAfter(LocalDateTime.now(java.time.ZoneOffset.UTC)));
    if (candidates.size() >= minResults)
        break;
}
